function SectionHeading({ index, eyebrow, title, description, align='left' }: {
  index: string; eyebrow: string; title: ReactNode; description?: string; align?: 'left'|'center';
}) {
  return <div className={`section-head ${align === 'center' ? 'mx-auto text-center' : ''}`}>
    <div className={`mb-5 flex items-center gap-3 ${align === 'center' ? 'justify-center' : ''}`}><span className="section-index">{index}</span><span className="eyebrow">{eyebrow}</span></div>
    <h2 className="section-title">{title}</h2>
    {description && <p className="section-description">{description}</p>}
  </div>;
}
function Reveal({ children, className='', delay=0 }: { children:ReactNode; className?:string; delay?:number }) {
  const reduced = useReducedMotion();
  return <motion.div initial={reduced ? false : { opacity:0, y:22 }} whileInView={{ opacity:1, y:0 }} viewport={{ once:true, amount:.12 }} transition={{ duration:.54, delay, ease:[.2,.7,.3,1] }} className={className}>{children}</motion.div>;
}
function IconBox({ name, large=false }: {name:string;large?:boolean}) {
  return <div className={`icon-box ${large ? 'h-13 w-13' : 'h-11 w-11'}`}><FeatureIcon name={name} size={large ? 24 : 20}/></div>;
}
function MissingLink({ title, children }: {title:string;children:ReactNode}) {
  return <span title={`${title} — add your real URL in src/config.ts`} className="inline-flex cursor-not-allowed items-center gap-2 opacity-50" aria-label={`${title} not configured`}>{children}</span>;
}
function Social({ platform, url, icon=false }: {platform:'LinkedIn'|'GitHub';url:string;icon?:boolean}) {
  const Icon = platform === 'LinkedIn' ? Linkedin : Github;
  if (!url) return <MissingLink title={platform}><span className={`social-link ${icon ? 'social-icon' : ''}`}><Icon size={17} />{!icon && platform}<span className="sr-only">unconfigured</span></span></MissingLink>;
  return <a className={`social-link ${icon ? 'social-icon' : ''}`} href={url} target="_blank" rel="noopener noreferrer" aria-label={platform}><Icon size={17}/>{!icon && platform}{!icon && <ArrowUpRight size={13}/>}</a>;
}
function Header({ theme, toggleTheme }: {theme:'light'|'dark';toggleTheme:()=>void}) {
  const [open, setOpen] = useState(false);
  useEffect(()=>{const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape')setOpen(false)};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[]);
  return <header className="sticky top-0 z-50 border-b border-slate-200/80 bg-white/92 backdrop-blur-xl dark:border-slate-700/70 dark:bg-[#0c161d]/92">
    <div className="container-wide flex h-[74px] items-center justify-between gap-4">
      <a href="#home" aria-label="Back to top" className="flex shrink-0 items-center gap-2.5 focus-ring"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#0d9488] text-white shadow-[0_8px_20px_-10px_#0d9488]"><ShieldCheck size={21} strokeWidth={2.15}/></span><span className="flex flex-col leading-tight"><strong className="text-[15px] font-extrabold tracking-[.025em] text-slate-900 dark:text-white">{profile.shortName}</strong><span className="mt-1 font-mono text-[9px] uppercase tracking-[.13em] text-slate-500 dark:text-slate-400">Security portfolio</span></span></a>
      <nav className="hidden items-center gap-6 lg:flex" aria-label="Primary navigation">{links.map(l=><a key={l.href} href={l.href} className="nav-link">{l.label}</a>)}</nav>
      <div className="flex items-center gap-2"><button type="button" onClick={toggleTheme} className="icon-button" aria-label={`Switch to ${theme==='dark'?'light':'dark'} mode`} title={`Switch to ${theme==='dark'?'light':'dark'} mode`}>{theme==='dark'?<Sun size={19}/>:<Moon size={19}/>}</button><a href="#contact" className="button button-primary hidden px-4 py-2.5 text-xs sm:inline-flex">Let's connect <ArrowUpRight size={15}/></a><button type="button" onClick={()=>setOpen(!open)} className="icon-button lg:hidden" aria-expanded={open} aria-controls="mobile-nav" aria-label={open?'Close navigation':'Open navigation'}>{open?<X size={21}/>:<Menu size={21}/>}</button></div>
    </div>
    <AnimatePresence>{open && <motion.nav id="mobile-nav" initial={{height:0,opacity:0}} animate={{height:'auto',opacity:1}} exit={{height:0,opacity:0}} transition={{duration:.18}} className="overflow-hidden border-t border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-950 lg:hidden" aria-label="Mobile navigation"><div className="container-wide flex flex-col py-3">{links.map(l=><a key={l.href} href={l.href} onClick={()=>setOpen(false)} className="block rounded-lg px-3 py-3 text-sm font-semibold text-slate-700 hover:bg-slate-50 dark:text-slate-200 dark:hover:bg-slate-800">{l.label}</a>)}</div></motion.nav>}</AnimatePresence>
  </header>;
}
